CREATE TABLE dim_customer(customer_id INTEGER PRIMARY KEY,customer_name TEXT,region TEXT,city TEXT); CREATE TABLE dim_product(product_id INTEGER PRIMARY KEY,product_name TEXT,category TEXT,unit_price REAL,cost_rate REAL); CREATE TABLE fact_sales(order_id INTEGER PRIMARY KEY,order_date DATE,customer_id INTEGER,product_id INTEGER,quantity INTEGER,discount_pct REAL,net_sales REAL,profit REAL,sales_channel TEXT,payment_method TEXT,order_status TEXT);